// Storage Manager sidebar panel.
// Generated by aurora@aurora-smart-home (ha-integration-dev skill)
// https://github.com/tonylofgren/aurora-smart-home
import { LitElement, html, nothing } from "lit";
import { DatabaseSection, TIER_DAYS } from "./database-section.js";
import { HealthSection } from "./health-section.js";
import { styles } from "./styles.js";
import { translator, locale } from "./i18n.js";
import { bytes, number, percent, relativeTime, dateTime } from "./format.js";

const DOMAIN = "storage_manager";
const TABS = ["overview", "database", "backups", "files"];
const PAGE = 150;
const CATEGORY_COLORS = {
  homeassistant: "var(--sm-c1)",
  apps_data: "var(--sm-c2)",
  apps_config: "var(--sm-c6)",
  backup: "var(--sm-c4)",
  media: "var(--sm-c3)",
  share: "var(--sm-c5)",
  ssl: "var(--sm-c6)",
  system: "var(--sm-c7)",
};
const REC_ICONS = {
  backups: "mdi:backup-restore",
  backups_rotation_off: "mdi:backup-restore",
  backups_offsite: "mdi:cloud-alert",
  files: "mdi:file-cabinet",
  orphans: "mdi:ghost-outline",
  statistics: "mdi:chart-box-outline",
  repack: "mdi:database-refresh",
  top_entities: "mdi:database-alert",
  retention: "mdi:calendar-clock",
};

const svgIcon = (path) => html`<svg viewBox="0 0 24 24" width="24" height="24" aria-hidden="true">
  <path fill="currentColor" d=${path}></path></svg>`;
const MENU = "M3,6H21V8H3V6M3,11H21V13H3V11M3,16H21V18H3V16Z";
const REFRESH = "M17.65,6.35C16.2,4.9 14.21,4 12,4A8,8 0 0,0 4,12A8,8 0 0,0 12,20C15.73,20 18.84,17.45 19.73,14H17.65C16.83,16.33 14.61,18 12,18A6,6 0 0,1 6,12A6,6 0 0,1 12,6C13.66,6 15.14,6.69 16.22,7.78L13,11H20V4L17.65,6.35Z";

class StorageManagerPanel extends HealthSection(DatabaseSection(LitElement)) {
  static properties = {
    hass: { attribute: false },
    narrow: { type: Boolean },
    route: { attribute: false },
    panel: { attribute: false },
    _tab: { state: true },
    _overview: { state: true },
    _entities: { state: true },
    _backups: { state: true },
    _health: { state: true },
    _repackConvert: { state: true },
    _draft: { state: true },
    _selected: { state: true },
    _search: { state: true },
    _domain: { state: true },
    _onlyChanged: { state: true },
    _onlyOrphans: { state: true },
    _sort: { state: true },
    _limit: { state: true },
    _dialog: { state: true },
    _detail: { state: true },
    _view: { state: true },
    _openGroups: { state: true },
    _onlyAdvice: { state: true },
    _settingsOpen: { state: true },
    _settingsDraft: { state: true },
    _toast: { state: true },
    _working: { state: true },
    _error: { state: true },
  };

  static styles = styles;

  constructor() {
    super();
    const hash = window.location.hash.replace("#", "");
    this._tab = TABS.includes(hash) ? hash : "overview";
    this._draft = new Map();
    this._selected = new Set();
    this._search = "";
    this._domain = "";
    this._onlyChanged = false;
    this._onlyOrphans = false;
    this._sort = "size";
    this._limit = PAGE;
    this._working = null;
  }

  get t() {
    return translator(this.hass);
  }

  get lang() {
    return locale(this.hass);
  }

  connectedCallback() {
    super.connectedCallback();
    this._hashListener = () => {
      const hash = window.location.hash.replace("#", "");
      if (TABS.includes(hash) && hash !== this._tab) this._setTab(hash, false);
    };
    window.addEventListener("hashchange", this._hashListener);
  }

  disconnectedCallback() {
    super.disconnectedCallback();
    window.removeEventListener("hashchange", this._hashListener);
    this._unsubscribe?.then((unsub) => unsub()).catch(() => {});
    this._unsubscribe = undefined;
  }

  updated(changed) {
    if (changed.has("hass") && this.hass && !this._started) {
      this._started = true;
      this._loadOverview();
      this._loadTab(this._tab);
      this._unsubscribe = this.hass.connection
        .subscribeMessage(() => this._scheduleReload(), { type: `${DOMAIN}/subscribe` })
        .catch(() => undefined);
    }
  }

  // ------------------------------------------------------------------ data

  _ws(type, data = {}) {
    return this.hass.callWS({ type: `${DOMAIN}/${type}`, ...data });
  }

  _scheduleReload() {
    clearTimeout(this._reloadTimer);
    this._reloadTimer = setTimeout(() => this._loadOverview(), 400);
  }

  async _loadOverview() {
    try {
      this._overview = await this._ws("overview");
      this._error = undefined;
    } catch (err) {
      this._error = err.message || String(err);
    }
  }

  async _loadEntities() {
    try {
      this._entities = await this._ws("entities");
    } catch (err) {
      this._showToast(this.t("error", { msg: err.message }));
    }
  }

  async _loadBackups() {
    try {
      this._backups = await this._ws("backups");
    } catch (err) {
      this._showToast(this.t("error", { msg: err.message }));
    }
  }

  _loadTab(tab) {
    if (tab === "database" && !this._entities) this._loadEntities();
    if (tab === "backups") this._loadBackups();
    if (tab === "database" || tab === "backups") this._loadHealth();
  }

  _setTab(tab, pushHash = true) {
    this._tab = tab;
    if (pushHash) history.replaceState(null, "", `#${tab}`);
    this._loadTab(tab);
  }

  async _refreshAll() {
    this._working = "refresh";
    try {
      await this._ws("refresh");
      await this._loadOverview();
      if (this._tab === "database") await this._loadEntities();
      if (this._tab === "backups") await this._loadBackups();
    } finally {
      this._working = null;
    }
  }

  _showToast(text) {
    this._toast = text;
    clearTimeout(this._toastTimer);
    this._toastTimer = setTimeout(() => (this._toast = undefined), 5000);
  }

  _navigate(path) {
    history.pushState(null, "", path);
    window.dispatchEvent(new CustomEvent("location-changed", { detail: { replace: false } }));
  }

  _toggleMenu() {
    this.dispatchEvent(new CustomEvent("hass-toggle-menu", { bubbles: true, composed: true }));
  }

  // --------------------------------------------------------------- actions

  async _previewAndClean(targets, extra = {}) {
    let preview;
    try {
      preview = await this._ws("preview", { targets });
    } catch (err) {
      this._showToast(this.t("error", { msg: err.message }));
      return;
    }
    const items = [];
    for (const target of targets) {
      const p = preview[target];
      if (!p) continue;
      if (target === "backups") p.items.forEach((b) => items.push(`${b.name} · ${bytes(b.bytes, this.lang)}`));
      else if (target === "files") p.items.forEach((f) => items.push(`${this.t(`hog_${f.name}`)} · ${bytes(f.bytes, this.lang)}`));
      else if (target === "orphans") items.push(`${this.t("rec_orphans")}: ${p.items.length} · ${bytes(p.bytes, this.lang)}`);
      else if (target === "statistics") items.push(`${this.t("rec_statistics")}: ${p.items.length}`);
      else if (target === "purge") items.push(`${this.t("obsolete_purge")}: ${number(p.rows, this.lang)} · ${bytes(p.bytes, this.lang)}`);
      else if (target === "repack") items.push(`${this.t("rec_repack")} · ${bytes(p.bytes, this.lang)} – ${this._repackPlanText(p.plan)}`);
      else if (target === "docker") items.push(this.t("docker_title"));
    }
    const plan = preview.repack?.plan;
    const canConvert = !!plan?.can_convert;
    this._repackConvert = true;
    const blockedSpace = preview.safety && !preview.safety.space.ok;
    this._dialog = {
      title: this.t("confirm_title"),
      body: () => html`<p>${this.t("confirm_cleanup")}</p>
        <ul>${items.map((i) => html`<li>${i}</li>`)}</ul>
        ${preview.total ? html`<p><b>${this.t("confirm_total", { bytes: bytes(preview.total, this.lang) })}</b></p>` : nothing}
        ${this._safetyItems(preview.safety)}
        ${canConvert
          ? html`<label class="check-line"><input type="checkbox" .checked=${this._repackConvert}
              @change=${(e) => (this._repackConvert = e.target.checked)} />
              <span>${this.t("repack_convert")}<br /><span class="muted small">${this.t("repack_convert_hint")}</span></span></label>`
          : nothing}`,
      confirm: this.t("free_now"),
      danger: true,
      disabled: blockedSpace,
      action: () => this._clean(targets, canConvert ? { ...extra, convert: this._repackConvert } : extra),
    };
  }

  async _clean(targets, extra = {}) {
    this._working = targets.join(",");
    try {
      const result = await this._ws("clean", { targets, ...extra });
      const msg = result.freed > 0 ? this.t("done_freed", { bytes: bytes(result.freed, this.lang) }) : this.t("done");
      if (result.blocked) {
        this._handleBlocked(result.blocked, () => this._clean(targets, { ...extra, skip_backup: true }));
      } else {
        const backup = result.backup ? ` ${this.t("backup_used", { name: result.backup.name })}` : "";
        this._showToast(result.errors?.length ? `${msg}${backup} ${result.errors.join("; ")}` : `${msg}${backup}`);
      }
      await this._loadOverview();
      if (this._entities) await this._loadEntities();
      if (this._tab === "backups") await this._loadBackups();
    } catch (err) {
      this._showToast(this.t("error", { msg: err.message }));
    } finally {
      this._working = null;
    }
  }

  async _analyze() {
    this._working = "analyze";
    try {
      const res = await this._ws("analyze");
      if (res.cancelled) this._showToast(this.t("analysis_stopped"));
      await Promise.all([this._loadOverview(), this._loadEntities()]);
    } catch (err) {
      this._showToast(this.t("error", { msg: err.message }));
    } finally {
      this._working = null;
    }
  }

  _confirmRestart() {
    this._dialog = {
      title: this.t("restart"),
      body: html`<p>${this.t("restart_confirm")}</p>`,
      confirm: this.t("restart"),
      danger: true,
      action: () => this.hass.callService("homeassistant", "restart"),
    };
  }

  async _importGuiRecorder() {
    try {
      const res = await this._ws("import_gui_recorder");
      this._showToast(this.t("gui_recorder_done", { n: res.imported }));
      await Promise.all([this._loadOverview(), this._loadEntities()]);
    } catch (err) {
      this._showToast(this.t("error", { msg: err.message }));
    }
  }

  // ----------------------------------------------------------------- draft

  _effective(row) {
    const d = this._draft.get(row.entity_id);
    if (d) return d.value;
    return row.excluded ? "excluded" : row.tier;
  }

  _original(row) {
    return row.excluded ? "excluded" : row.tier;
  }

  _setValue(rows, value) {
    const draft = new Map(this._draft);
    for (const row of rows) {
      if (row.excluded_by_yaml) continue;
      if (value === this._original(row)) draft.delete(row.entity_id);
      else draft.set(row.entity_id, { value, row });
    }
    this._draft = draft;
  }

  _draftEstimate() {
    let total = 0;
    for (const { value, row } of this._draft.values()) {
      if (!(value in TIER_DAYS) || !row.rows) continue;
      const keep = TIER_DAYS[value];
      const kept = keep === 0 ? 0 : Math.min(row.rows_24h * keep, row.rows);
      total += row.est_state_bytes * (1 - kept / row.rows);
    }
    return Math.max(total, 0);
  }

  async _applyDraft() {
    const retention = {};
    const excluded = {};
    for (const [entityId, { value, row }] of this._draft) {
      const wasExcluded = row.excluded;
      if (value === "excluded") {
        if (!wasExcluded) excluded[entityId] = true;
      } else {
        if (wasExcluded) excluded[entityId] = false;
        if (value !== row.tier) retention[entityId] = value;
      }
    }
    await this._sendApply({ retention, excluded, purge_now: true });
  }

  async _sendApply(payload) {
    this._working = "apply";
    try {
      const res = await this._ws("apply", payload);
      this._draft = new Map();
      this._selected = new Set();
      if (res.blocked) {
        this._showToast(this.t("applied_purge_waits"));
        this._handleBlocked(res.blocked, () => this._sendApply({ ...payload, skip_backup: true }));
      } else {
        this._showToast(res.backup ? `${this.t("applied")} ${this.t("backup_used", { name: res.backup.name })}` : this.t("applied"));
      }
      await Promise.all([this._loadOverview(), this._loadEntities()]);
      if (res.packages_missing) this._showToast(this.t("packages_banner"));
    } catch (err) {
      this._showToast(this.t("error", { msg: err.message }));
    } finally {
      this._working = null;
    }
  }

  // ---------------------------------------------------------------- render

  render() {
    if (!this.hass) return nothing;
    const t = this.t;
    return html`
      <header>
        <div class="toolbar">
          ${this.narrow
            ? html`<button class="icon-btn" @click=${this._toggleMenu} aria-label="menu">${svgIcon(MENU)}</button>`
            : nothing}
          <div class="title">${t("title")}</div>
          <button class="icon-btn" title=${t("refresh")} aria-label=${t("refresh")}
            ?disabled=${!!this._working} @click=${this._refreshAll}>${svgIcon(REFRESH)}</button>
        </div>
        <nav class="tabs" role="tablist">
          ${TABS.map(
            (tab) => html`<button role="tab" aria-selected=${tab === this._tab ? "true" : "false"}
              @click=${() => this._setTab(tab)}>${t(`tab_${tab}`)}</button>`
          )}
        </nav>
      </header>
      <main>
        ${this._error ? html`<div class="banner"><div class="txt">${t("error", { msg: this._error })}</div></div>` : nothing}
        ${this._busyBanner()}
        ${!this._overview
          ? html`<div class="center"><span class="spinner"></span><p class="muted">${t("loading")}</p></div>`
          : this._renderTab()}
      </main>
      ${this._renderDraftBar()} ${this._toast ? html`<div class="toast" role="status">${this._toast}</div>` : nothing}
      ${this._renderDialog()}
    `;
  }

  _busyBanner() {
    const busy = this._overview?.data?.busy || (this._working && this._working !== "refresh" ? this._working : null);
    if (!busy) return nothing;
    return html`<div class="banner info"><span class="spinner"></span><div class="txt">${this.t("busy", { what: this._busyText(busy) })}</div></div>`;
  }

  _renderTab() {
    switch (this._tab) {
      case "database":
        return this._renderDatabase();
      case "backups":
        return this._renderBackups();
      case "files":
        return this._renderFiles();
      default:
        return this._renderOverview();
    }
  }

  // -------------------------------------------------------------- overview

  _renderOverview() {
    const t = this.t;
    const { data, recommendations, history } = this._overview;
    const d = data.disk;
    const fc = data.forecast;
    let growth;
    if (fc.growth_per_day === null) growth = t("growth_unknown");
    else if (fc.days_until_full !== null)
      growth = t("growth_full", { growth: bytes(fc.growth_per_day, this.lang), days: Math.round(fc.days_until_full) });
    else if (fc.growth_per_day > 1024 * 1024) growth = t("growth_ok", { growth: bytes(fc.growth_per_day, this.lang) });
    else growth = t("growth_none");

    const segments = this._segments(data);
    const lowSpace = 100 - d.percent_used < this._overview.options.low_space_percent;
    const soonFull = fc.days_until_full !== null && fc.days_until_full < this._overview.options.forecast_warning_days;
    return html`
      ${lowSpace || soonFull
        ? html`<div class="banner"><ha-icon icon="mdi:harddisk-remove"></ha-icon>
            <div class="txt">${!lowSpace
              ? t("forecast_banner", { days: Math.round(fc.days_until_full) })
              : data.reclaimable.total > 0
              ? t("low_space_banner", { free: bytes(d.free, this.lang), reclaim: bytes(data.reclaimable.total, this.lang) })
              : t("low_space_banner_db", { free: bytes(d.free, this.lang) })}</div>
            ${data.reclaimable.files + data.reclaimable.backups > 0
              ? html`<button class="btn primary" ?disabled=${!!this._working}
                  @click=${() => this._previewAndClean(this._safeTargets())}>${t("safe_cleanup")}</button>`
              : html`<button class="btn" @click=${() => this._setTab("database")}>${t("tab_database")}</button>`}
          </div>`
        : nothing}
      <div class="card">
        <div class="hero">
          <div>
            <div class="big">${bytes(d.free, this.lang)}</div>
            <div class="muted">${t("free")} ${t("of")} ${bytes(d.total, this.lang)}</div>
          </div>
          <div>
            <div class="row"><b>${percent(d.percent_used / 100, this.lang)} ${t("used")}</b></div>
            <div class="stack" role="img" aria-label=${`${percent(d.percent_used / 100, this.lang)} ${t("used")}`}>
              ${segments.map((s) => html`<div style="width:${s.share * 100}%;background:${s.color}" title=${`${s.label}: ${bytes(s.bytes, this.lang)}`}></div>`)}
            </div>
            <div class="legend">
              ${segments.map((s) => html`<span><i class="dot" style="background:${s.color}"></i>${s.label} ${bytes(s.bytes, this.lang)}</span>`)}
            </div>
            <p class="muted small" style="margin:10px 0 0">${growth}</p>
          </div>
        </div>
      </div>

      <div class="card">
        <h2>${t("reclaim_title")}<span class="spacer"></span>
          ${data.reclaimable.total > 0
            ? html`<span class="muted small">${t("reclaim_total", { bytes: bytes(data.reclaimable.total, this.lang) })}</span>`
            : nothing}
          ${data.retention_potential?.bytes
            ? html`<span class="muted small">&nbsp;· ${t("reclaim_retention", { bytes: bytes(data.retention_potential.bytes, this.lang) })}</span>`
            : nothing}
        </h2>
        ${recommendations.length === 0
          ? html`<p class="muted">${t("reclaim_none")}</p>`
          : recommendations.map((r) => this._renderRec(r))}
      </div>

      <div class="grid2">
        <div class="card">
          <h2>${t("breakdown_title")}</h2>
          ${this._renderBreakdown(data)}
        </div>
        <div class="card">
          <h2>${t("history_title")}<span class="spacer"></span>
            <span class="muted small">${t("history_total", { bytes: bytes(data.freed_total, this.lang) })}</span></h2>
          ${history.length === 0
            ? html`<p class="muted">${t("history_empty")}</p>`
            : history.slice(0, 8).map(
                (h) => html`<div class="list-row">
                  <div>${t(`action_${h.action}`)}<div class="muted small">${dateTime(h.time, this.lang)}${(h.details?.targets || []).length
                    ? ` · ${h.details.targets.map((x) => t(`target_${x}`)).join(", ")}`
                    : ""}${h.details?.blocked ? ` · ${t("history_blocked")}` : ""}</div></div>
                  <div></div>
                  <div class="num"><b>${bytes(h.freed_bytes, this.lang)}</b></div>
                </div>`
              )}
        </div>
      </div>
    `;
  }

  _safeTargets() {
    return this._overview.options.backup_rotation ? ["backups", "files"] : ["files"];
  }

  _segments(data) {
    const d = data.disk;
    const out = [];
    const children = data.breakdown?.children;
    if (children?.length) {
      for (const c of children) {
        if (!c.used_bytes) continue;
        out.push({
          id: c.id,
          label: this.t(`cat_${c.id}`) !== `cat_${c.id}` ? this.t(`cat_${c.id}`) : c.label || c.id,
          bytes: c.used_bytes,
          share: c.used_bytes / d.total,
          color: CATEGORY_COLORS[c.id] || "var(--sm-c7)",
        });
      }
      out.sort((a, b) => b.bytes - a.bytes);
    } else {
      out.push({ id: "used", label: this.t("used_cap"), bytes: d.used, share: d.used / d.total, color: "var(--sm-c1)" });
    }
    return out;
  }

  _renderRec(r) {
    const t = this.t;
    const vars = {
      count: r.count ?? "",
      share: r.share ? percent(r.share, this.lang) : "",
    };
    const title = t(`rec_${r.id}`, vars);
    const desc = t(`rec_${r.id}_desc`, vars);
    const busy = !!this._working;
    return html`<div class="rec">
      <div class="ico"><ha-icon icon=${REC_ICONS[r.id] || "mdi:broom"}></ha-icon></div>
      <div>
        <div class="t">${title}</div>
        <div class="muted small">${desc}</div>
      </div>
      <div class="act row">
        ${r.bytes ? html`<span class="amount">${bytes(r.bytes, this.lang)}</span>` : nothing}
        ${r.action === "clean"
          ? html`<button class="btn" ?disabled=${busy} @click=${() => this._previewAndClean(r.targets)}>${t("preview")}</button>`
          : html`<button class="btn" @click=${() => this._setTab(r.view)}>${t("open")}</button>`}
      </div>
    </div>`;
  }

  _renderBreakdown(data) {
    const t = this.t;
    const tree = data.breakdown;
    if (!tree?.children?.length) {
      return html`<p class="muted small">${t("breakdown_unavailable")}</p>
        ${this._bars([{ label: t("used_cap"), bytes: data.disk.used }, { label: t("cat_free"), bytes: data.disk.free }], data.disk.total)}`;
    }
    const names = data.addon_names || {};
    const rows = [];
    for (const c of tree.children) {
      rows.push({ label: t(`cat_${c.id}`) !== `cat_${c.id}` ? t(`cat_${c.id}`) : c.label || c.id, bytes: c.used_bytes, color: CATEGORY_COLORS[c.id] });
      if (c.id === "apps_data" && c.children?.length) {
        for (const a of c.children.slice(0, 6)) {
          rows.push({ label: names[a.id] || a.label || a.id, bytes: a.used_bytes, color: CATEGORY_COLORS.apps_data, indent: true });
        }
      }
    }
    return this._bars(rows, data.disk.total);
  }

  _bars(rows, total) {
    return rows.map(
      (r) => html`<div style="margin:8px 0 ${r.indent ? "6px 18px" : "10px"}">
        <div class="row small"><span>${r.label}</span><span class="spacer"></span><span class="muted">${bytes(r.bytes, this.lang)}</span></div>
        <div class="bar"><div style="width:${Math.max((r.bytes / total) * 100, 0.5)}%;background:${r.color || "var(--sm-c1)"}"></div></div>
      </div>`
    );
  }

  _renderDraftBar() {
    if (!this._draft.size || this._tab !== "database") return nothing;
    const t = this.t;
    const estimate = this._draftEstimate();
    return html`<div class="draftbar" role="region" aria-label=${t("draft", { n: this._draft.size })}>
      <div>
        <div class="txt">${t("draft", { n: this._draft.size })}</div>
        ${estimate > 0 ? html`<div class="muted small">${t("draft_estimate", { bytes: bytes(estimate, this.lang) })}</div>` : nothing}
      </div>
      <button class="btn" @click=${() => (this._draft = new Map())}>${t("discard")}</button>
      <button class="btn primary" ?disabled=${!!this._working} @click=${this._applyDraft}>${t("apply")}</button>
    </div>`;
  }

  // --------------------------------------------------------------- backups

  _renderBackups() {
    const t = this.t;
    const ov = this._overview;
    const summary = ov.data.backups;
    const opts = ov.options;
    if (!summary.available) return html`<div class="card"><p class="muted">${t("bk_unavailable")}</p></div>`;
    const plan = this._backups?.plan;
    return html`
      ${this._healthCard("backups")}
      <div class="card">
        <div class="kpis">
          <div class="kpi"><div class="v">${bytes(summary.local_total, this.lang)}</div><div class="l">${t("bk_kpi_local")}</div></div>
          <div class="kpi"><div class="v">${number(summary.local_count, this.lang)}</div><div class="l">${t("bk_kpi_count")}</div></div>
          <div class="kpi"><div class="v">${bytes(summary.deletable_bytes, this.lang)}</div><div class="l">${t("bk_kpi_deletable")}</div></div>
        </div>
        <p class="muted small" style="margin:12px 0 0">
          ${summary.rotation_enabled ? t("bk_rotation_on") : t("bk_rotation_off")} ·
          ${t("bk_schedule", { d: opts.keep_daily, w: opts.keep_weekly, m: opts.keep_monthly })}
          ${opts.require_offsite ? html`<br />${t("bk_offsite_required")}` : nothing}
        </p>
        <div class="row" style="margin-top:12px">
          <button class="btn" @click=${() => this._navigate(`/config/integrations/integration/${DOMAIN}`)}>${t("options")}</button>
          <span class="spacer"></span>
          <button class="btn primary danger" ?disabled=${!summary.deletable_count || !!this._working}
            @click=${() => this._previewAndClean(["backups"])}>${t("bk_apply")}</button>
        </div>
      </div>
      <div class="card">
        ${!plan
          ? html`<div class="center"><span class="spinner"></span></div>`
          : plan.length === 0
          ? html`<p class="muted">${t("bk_none")}</p>`
          : html`<table>
              <thead><tr><th>${t("col_backup")}</th><th class="num">${t("col_size")}</th><th>${t("col_locations")}</th><th>${t("col_action")}</th></tr></thead>
              <tbody>${plan.map(
                (b) => html`<tr>
                  <td><div>${b.name}</div><div class="muted small">${dateTime(b.date, this.lang)}</div></td>
                  <td class="num">${bytes(b.local_size, this.lang)}</td>
                  <td>${b.local_agents.map((a) => html`<span class="tag" title=${a}>${this._agentName(a)}</span>`)}${b.remote_agents.map((a) => html`<span class="tag ok" title=${a}>${this._agentName(a)}</span>`)}</td>
                  <td>${b.action === "delete_local"
                    ? html`<span class="tag bad">${t("bk_reason_rotated")}</span>`
                    : html`<span class=${b.reason === "only_local" ? "tag warn" : "tag"}>${t(`bk_reason_${b.reason}`)}</span>`}</td>
                </tr>`
              )}</tbody>
            </table>`}
      </div>
    `;
  }

  _agentName(agentId) {
    if (agentId === "hassio.local" || agentId === "backup.local") return this.t("bk_local");
    if (agentId === "cloud.cloud") return "Home Assistant Cloud";
    const [domain, name] = agentId.split(".", 2);
    if (domain === "hassio" && name) return name;
    return domain.replace(/_/g, " ").replace(/\b\w/g, (c) => c.toUpperCase());
  }

  // ----------------------------------------------------------------- files

  _renderFiles() {
    const t = this.t;
    const data = this._overview.data;
    const scan = data.files || { hogs: [], large_files: [] };
    const busy = !!this._working;
    const repackPlan = data.database.repack;
    const repackOk = repackPlan
      ? !!repackPlan.method && (repackPlan.free_pages_bytes > 0 || repackPlan.can_convert)
      : data.disk.free > (data.database.size || 0) * 1.1;
    return html`
      <div class="card">
        <h2>${t("files_hogs")}</h2>
        ${scan.hogs.length === 0
          ? html`<p class="muted">${t("files_none")}</p>`
          : scan.hogs.map(
              (h) => html`<div class="list-row">
                <div>
                  <div>${t(`hog_${h.key}`)} <span class=${h.safety === "safe" ? "tag ok" : "tag warn"}>${t(`safety_${h.safety}`)}</span></div>
                  <div class="muted small" style="overflow-wrap:anywhere">${h.paths.slice(0, 3).join(", ")}${h.paths.length > 3 ? " …" : ""}</div>
                </div>
                <div class="num"><b>${bytes(h.size_bytes, this.lang)}</b></div>
                <button class="btn danger" ?disabled=${busy}
                  @click=${() => this._confirmHog(h)}>${t("delete")}</button>
              </div>`
            )}
      </div>

      <div class="card">
        <h2>${t("maintenance")}</h2>
        <div class="list-row">
          <div><div>${t("repack_title")}</div><div class="muted small">${repackPlan ? this._repackPlanText(repackPlan) : repackOk ? t("repack_desc") : t("repack_impossible")}</div></div>
          <div class="num">${data.reclaimable.repack ? bytes(data.reclaimable.repack, this.lang) : ""}</div>
          <button class="btn" ?disabled=${busy || !repackOk} @click=${() => this._previewAndClean(["repack"])}>${t("run")}</button>
        </div>
        ${data.is_hassio
          ? html`<div class="list-row">
              <div><div>${t("docker_title")}</div><div class="muted small">${t("docker_desc")}</div></div>
              <div></div>
              <button class="btn" ?disabled=${busy} @click=${() => this._previewAndClean(["docker"])}>${t("run")}</button>
            </div>`
          : nothing}
      </div>

      ${scan.large_files.length
        ? html`<div class="card"><h2>${t("files_large")}</h2>
            <p class="muted small">${t("files_large_hint")}</p>
            ${scan.large_files.map((f) => html`<div class="list-row"><div style="overflow-wrap:anywhere"><code>${f.path}</code></div><div></div><div class="num">${bytes(f.size_bytes, this.lang)}</div></div>`)}</div>`
        : nothing}
    `;
  }

  _confirmHog(h) {
    const t = this.t;
    this._dialog = {
      title: t(`hog_${h.key}`),
      body: html`<p>${t("confirm_cleanup")}</p><ul>${h.paths.map((p) => html`<li><code>${p}</code></li>`)}</ul>
        <p><b>${t("confirm_total", { bytes: bytes(h.size_bytes, this.lang) })}</b></p>`,
      confirm: t("delete"),
      danger: true,
      action: () => this._clean(["files"], { hog_keys: [h.key] }),
    };
  }

  // ---------------------------------------------------------------- dialog

  _renderDialog() {
    const d = this._dialog;
    if (!d) return nothing;
    const close = () => (this._dialog = undefined);
    return html`<div class="scrim" @click=${(e) => e.target === e.currentTarget && close()}
      @keydown=${(e) => e.key === "Escape" && close()}>
      <div class="dialog" role="dialog" aria-modal="true" aria-label=${d.title}>
        <h3>${d.title}</h3>
        ${typeof d.body === "function" ? d.body() : d.body}
        <div class="actions">
          <button class="btn" @click=${close}>${this.t("cancel")}</button>
          <button class=${d.danger ? "btn primary danger" : "btn primary"} autofocus ?disabled=${!!d.disabled}
            @click=${() => { close(); d.action(); }}>${d.confirm}</button>
        </div>
      </div>
    </div>`;
  }
}

if (!customElements.get("storage-manager-panel")) {
  customElements.define("storage-manager-panel", StorageManagerPanel);
}
